#pragma once

#include <string>
#include <vector>
#include <optional>
#include <cstdint>

namespace ptv {

struct MentorLine {
    std::string speaker;
    std::string text;
    float ttl_s{3.0f};
    // Optional lightweight VFX hint (consumed by other mechanics listening to CTag)
    // Example payload emitted as: vfx.spawn:{"asset_id":"central_battery_structure","ttl_s":2.0}
    std::optional<std::string> vfx_asset_id;
};

struct MentorSessionState {
    std::vector<MentorLine> lines;
    std::size_t cursor{0};
    bool mute_vo{false};
};

// Topic keys expected via builtin.dialogue_trigger params_json
// topic: "onboarding" | "failure_tip" | "recharge_prompt"
// scene (optional): "central_battery_plaza" | "training_arena"
// failure_kind (optional): "hazard" | "timed_out" | "low_energy"

} // namespace ptv

#include "mentor_dialogue_shared.h"

#include <string>
#include <vector>

namespace ptv {

static std::vector<MentorLine> onboarding_central_plaza() {
    return {
        {"Mentor", "Welcome, recruit. Keep your stance relaxed and your gaze level. We'll begin with simple movement.", 4.0f, std::nullopt},
        {"Mentor", "Hover is enabled here. A light touch goes farther than force.", 3.5f, std::nullopt},
        {"Mentor", "Your ring shapes intent. Try a basic shield or a bolt to feel the response.", 4.0f, std::nullopt}
    };
}

static std::vector<MentorLine> onboarding_training_arena() {
    return {
        {"Mentor", "This arena is for practice. Watch your spacing and read enemy tells.", 3.5f, std::nullopt},
        {"Mentor", "Form follows focus. Short bursts build confidence—then commit.", 3.5f, std::nullopt},
        {"Mentor", "Defend, reposition, then strike. You'll set the rhythm, not them.", 3.5f, std::nullopt}
    };
}

static std::vector<MentorLine> failure_tip_generic() {
    return {
        {"Mentor", "Breathe. Reset your stance. Use a barrier to buy a moment.", 3.0f, std::nullopt},
        {"Mentor", "Angles matter. Step off the threat line, then answer with purpose.", 3.0f, std::nullopt}
    };
}

static std::vector<MentorLine> failure_tip_hazard() {
    return {
        {"Mentor", "Hazards punish hurry. Mark the pattern, then move between beats.", 3.2f, std::nullopt},
        {"Mentor", "A small platform can bridge danger—shape it steady, then cross.", 3.2f, std::nullopt}
    };
}

static std::vector<MentorLine> recharge_prompt_lines() {
    return {
        {"Mentor", "Your charge is low. Center yourself at the station and let the light flow.", 3.5f, std::nullopt},
        {"Mentor", "Steady breath in, slow breath out. Focus gathers and the ring answers.", 3.5f, std::nullopt}
    };
}

std::vector<MentorLine> build_lines_for_topic(const std::string& topic,
                                              const std::string& scene,
                                              const std::string& failure_kind)
{
    if (topic == "onboarding") {
        if (scene == "central_battery_plaza") return onboarding_central_plaza();
        if (scene == "training_arena") return onboarding_training_arena();
        // Default onboarding
        return {
            {"Mentor", "Welcome. We start simple—move with intent and stay aware.", 3.5f, std::nullopt},
            {"Mentor", "Test a light construct. Feel how control tracks your focus.", 3.5f, std::nullopt}
        };
    }
    if (topic == "failure_tip") {
        if (failure_kind == "hazard") return failure_tip_hazard();
        return failure_tip_generic();
    }
    if (topic == "recharge_prompt") {
        return recharge_prompt_lines();
    }
    // Fallback
    return { {"Mentor", "Steady now. Choose the next clear step and take it.", 3.0f, std::nullopt} };
}

} // namespace ptv

#include "mentor_dialogue_shared.h"

#include <nlohmann/json.hpp>
#include <string>

namespace ptv {

struct ParsedTrigger {
    std::string topic;
    std::string scene;
    std::string failure_kind;
    bool mute_vo{false};
};

static ParsedTrigger parse_trigger_params(const nlohmann::json& j) {
    ParsedTrigger out;
    if (j.is_object()) {
        out.topic = j.value("topic", std::string{});
        out.scene = j.value("scene", std::string{});
        out.failure_kind = j.value("failure_kind", std::string{});
        out.mute_vo = j.value("mute_vo", false);
        // Accessibility hint: if subtitles_only true, also mute VO
        if (j.value("subtitles_only", false)) out.mute_vo = true;
    }
    if (out.topic.empty()) out.topic = "onboarding"; // sensible default
    return out;
}

// Emit lightweight tag protocol via CTag strings on the mentor entity.
// Other systems (HUD, VFX, audio) may consume these.
//  - subtitle.show:{"speaker":"..","text":"..","ttl":3.0}
//  - dialogue.play:{"speaker":"..","text":".."}
//  - vfx.spawn:{"asset_id":"..","ttl_s":2.0}
static void emit_line_tags(class World& world, std::uint32_t entity,
                           const MentorLine& line,
                           bool mute_vo) {
    if (!world.valid(entity)) return;
    // Push subtitles
    {
        std::string payload = std::string("subtitle.show:{\"speaker\":\"") + line.speaker +
                              "\",\"text\":\"" + line.text +
                              "\",\"ttl\":" + std::to_string(line.ttl_s) + "}";
        world.emplace_or_replace<CTag>(entity, CTag{ std::vector<std::string>{ payload } });
    }
    // Optionally push VO request
    if (!mute_vo) {
        std::string payload = std::string("dialogue.play:{\"speaker\":\"") + line.speaker +
                              "\",\"text\":\"" + line.text + "\"}";
        if (world.has<CTag>(entity)) {
            auto tags = world.get<CTag>(entity).tags; // copy then replace with appended
            tags.push_back(payload);
            world.emplace_or_replace<CTag>(entity, CTag{ std::move(tags) });
        } else {
            world.emplace_or_replace<CTag>(entity, CTag{ std::vector<std::string>{ payload } });
        }
    }
    // Optional VFX hint
    if (line.vfx_asset_id.has_value()) {
        std::string payload = std::string("vfx.spawn:{\"asset_id\":\"") + *line.vfx_asset_id +
                              "\",\"ttl_s\":2.0}";
        if (world.has<CTag>(entity)) {
            auto tags = world.get<CTag>(entity).tags;
            tags.push_back(payload);
            world.emplace_or_replace<CTag>(entity, CTag{ std::move(tags) });
        } else {
            world.emplace_or_replace<CTag>(entity, CTag{ std::vector<std::string>{ payload } });
        }
    }
}

} // namespace ptv

#include "ptv/api/IDialogueHook.h"
#include "ptv/ecs/World.h"
#include <nlohmann/json.hpp>

#include <unordered_map>
#include <utility>
#include <string>

#include "mentor_dialogue_shared.h"

namespace ptv {

// Forward from mentor_lines.cpp
std::vector<MentorLine> build_lines_for_topic(const std::string& topic,
                                              const std::string& scene,
                                              const std::string& failure_kind);
// Forward from mentor_triggers.cpp
struct ParsedTrigger { std::string topic; std::string scene; std::string failure_kind; bool mute_vo; };
static ParsedTrigger parse_trigger_params(const nlohmann::json& j);
static void emit_line_tags(World& world, std::uint32_t entity, const MentorLine& line, bool mute_vo);

class MentorGuidanceDialogue final : public IDialogueHook {
public:
    void on_enter(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        auto parsed = parse_trigger_params(params);
        MentorSessionState st;
        st.lines = build_lines_for_topic(parsed.topic, parsed.scene, parsed.failure_kind);
        st.cursor = 0;
        st.mute_vo = parsed.mute_vo;
        sessions_[entity] = std::move(st);
        // Emit first line immediately
        auto& s = sessions_[entity];
        if (!s.lines.empty()) {
            emit_line_tags(world, entity, s.lines.front(), s.mute_vo);
            s.cursor = 1;
        }
        // Register a UI toast so the player knows how to advance (if the trigger supports it)
        {
            std::string toast = "ui.toast:{\"text\":\"Mentor guidance active — proceed at your pace.\",\"ttl\":2.0}";
            if (world.has<CTag>(entity)) {
                auto tags = world.get<CTag>(entity).tags;
                tags.push_back(toast);
                world.emplace_or_replace<CTag>(entity, CTag{ std::move(tags) });
            } else {
                world.emplace_or_replace<CTag>(entity, CTag{ std::vector<std::string>{ toast } });
            }
        }
    }

    // on_line is called when the driving system requests progression.
    // Expect params.next(bool) or params.ack(bool) to advance.
    void on_line(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        auto it = sessions_.find(entity);
        if (it == sessions_.end()) return;
        bool next = params.value("next", params.value("ack", true));
        if (!next) return;
        auto& s = it->second;
        if (s.cursor < s.lines.size()) {
            emit_line_tags(world, entity, s.lines[s.cursor], s.mute_vo);
            s.cursor++;
        } else {
            // No more lines: publish a gentle close signal the UI/HUD can consume.
            const char* k = "ui.toast:{\"text\":\"Guidance complete.\",\"ttl\":1.5}";
            if (world.has<CTag>(entity)) {
                auto tags = world.get<CTag>(entity).tags;
                tags.push_back(k);
                world.emplace_or_replace<CTag>(entity, CTag{ std::move(tags) });
            } else {
                world.emplace_or_replace<CTag>(entity, CTag{ std::vector<std::string>{ k } });
            }
        }
    }

    void on_exit(World& world, std::uint32_t entity) override {
        (void)world;
        sessions_.erase(entity);
    }

    std::string id() const override { return "generated.mentor_guidance_dialogue"; }

private:
    std::unordered_map<std::uint32_t, MentorSessionState> sessions_{};
};

} // namespace ptv

PTV_REGISTER_DIALOGUE_HOOK("generated.mentor_guidance_dialogue", ptv::MentorGuidanceDialogue)
